const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet({
  // Configure security headers
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  },
  // Hide 'X-Powered-By' header
  hidePoweredBy: true
}));

// Enable CORS with specific origin policy
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://trusted-domain.com',
  optionsSuccessStatus: 200
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes.',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Body parser with size limits to prevent DOS
app.use(express.json({
  limit: '10kb'
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);

  // Store request start time for response time tracking
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`Response: ${res.statusCode} - ${duration}ms`);
  });

  next();
});

// Health check with input validation
app.get('/health', [
  // Validate query parameters if present
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation error',
      details: errors.array(),
      code: 'VALIDATION_ERROR'
    });
  }

  // Return basic health status by default
  const healthStatus = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  };

  // Include detailed info if requested
  if (req.query.detailed === 'true') {
    healthStatus.environment = process.env.NODE_ENV || 'development';
    // Don't expose sensitive environment variables
    if (process.env.NODE_ENV === 'production') {
      delete healthStatus.environment; // Don't expose environment in prod
    }
  }

  res.json(healthStatus);
});

// Users endpoint with input validation and pagination
app.get('/users', [
  // Validate and sanitize pagination parameters
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('sort').optional().isIn(['name', 'id', 'email']).withMessage('Sort must be one of: name, id, email'),
  query('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation error',
      details: errors.array(),
      code: 'VALIDATION_ERROR'
    });
  }

  // Mock user data
  const mockUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Extract and sanitize query parameters with defaults
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;
  const sort = req.query.sort || 'id';
  const order = req.query.order || 'asc';

  // In a real application, you would use these parameters to query your database
  // For this example, we'll just mock the functionality

  // Sort the users
  let sortedUsers = [...mockUsers].sort((a, b) => {
    if (order === 'asc') {
      return a[sort] > b[sort] ? 1 : -1;
    } else {
      return a[sort] < b[sort] ? 1 : -1;
    }
  });

  // Calculate pagination
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

  // Return response with metadata
  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: mockUsers.length,
      pages: Math.ceil(mockUsers.length / limit)
    },
    sort: {
      by: sort,
      order
    }
  });
});

// Catch 404 errors for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
    code: 'NOT_FOUND'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Determine status code based on error type
  const status = error.status || error.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message || 'Internal server error',
    code: error.code || 'INTERNAL_ERROR',
    timestamp: new Date().toISOString()
  };

  // Add validation errors if present
  if (error.errors) {
    errorResponse.details = error.errors;
  }

  // Hide detailed error information in production
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = error.stack;
  }

  res.status(status).json(errorResponse);
});

// Graceful shutdown handling
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
  server.close(() => {
    process.exit(1);
  });
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Log the error and shut down gracefully
  server.close(() => {
    process.exit(1);
  });
});

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Allow the server to be closed programmatically for testing
module.exports = { app, server };

