const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.hidePoweredBy()); // Removes X-Powered-By header

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'RATE_LIMIT_EXCEEDED'
  }
});
app.use(limiter);

// Enhanced health check with validation and error handling
app.get('/health', 
  // Add query parameter validation if needed
  [
    query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean')
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          details: errors.array(),
          code: 'VALIDATION_ERROR'
        });
      }

      const healthData = {
        status: 'ok', 
        timestamp: new Date().toISOString(),
        version: process.env.npm_package_version || '1.0.0'
      };

      // Add detailed information if requested
      if (req.query.detailed === 'true') {
        healthData.environment = process.env.NODE_ENV || 'development';
        // Don't expose sensitive system info in production
        if (process.env.NODE_ENV !== 'production') {
          healthData.node_version = process.version;
        }
      }

      res.json(healthData);
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        code: 'INTERNAL_ERROR'
      });
    }
  }
);

// Users endpoint with proper validation and error handling
app.get('/users', 
  // Input validation for query parameters
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be 0 or greater'),
    query('sort').optional().isIn(['name', 'email', 'id']).withMessage('Sort field must be name, email, or id'),
    query('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc')
  ],
  (req, res) => {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          details: errors.array(),
          code: 'VALIDATION_ERROR'
        });
      }

      // Simulated user data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination if requested
      let result = [...users];

      const limit = req.query.limit ? parseInt(req.query.limit) : users.length;
      const offset = req.query.offset ? parseInt(req.query.offset) : 0;

      // Sort if requested
      if (req.query.sort) {
        result.sort((a, b) => {
          const direction = req.query.order === 'desc' ? -1 : 1;
          if (a[req.query.sort] < b[req.query.sort]) return -1 * direction;
          if (a[req.query.sort] > b[req.query.sort]) return 1 * direction;
          return 0;
        });
      }

      // Apply pagination
      result = result.slice(offset, offset + limit);

      // Return paginated result with metadata
      res.json({
        data: result,
        pagination: {
          limit,
          offset,
          total: users.length,
          has_more: offset + limit < users.length
        }
      });
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        code: 'INTERNAL_ERROR'
      });
    }
  }
);

// Error handling middleware (should be after all routes)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
    code: 'INTERNAL_ERROR',
    timestamp: new Date().toISOString()
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// Handle 404 - Must be after all routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path,
    code: 'NOT_FOUND'
  });
});

// Graceful shutdown handling
