require('dotenv').config();

const app = express();

// Security middleware
// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});

app.use(limiter);

// Security headers
app.use((req, res, next) => {
  // Security headers
  res.header('X-Content-Type-Options', 'nosniff');
  res.header('X-Frame-Options', 'DENY');
  res.header('X-XSS-Protection', '1; mode=block');
  res.header('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Set content security policy in production
  if (process.env.NODE_ENV === 'production') {
    res.header('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline'");
  }

  next();
});

// Body parser with size limits to prevent payload attacks
app.use(express.json({
  limit: '10kb'
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Input sanitization
app.use(sanitize());

// Health check with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if present
    if (req.query && Object.keys(req.query).length > 5) {
      return res.status(400).json({
        error: 'Too many query parameters provided'
      });
    }

    // Validate parameter names
    const allowedParams = ['verbose', 'details', 'format'];
    for (const param in req.query) {
      if (!allowedParams.includes(param)) {
        return res.status(400).json({
          error: `Query parameter '${param}' not allowed`
        });
      }
    }

    const response = {
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    // Add verbose output if requested
    if (req.query.verbose === 'true') {
      response.service = 'user-service';
      response.version = process.env.npm_package_version || '1.0.0';
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const allowedParams = ['limit', 'offset', 'sort', 'fields'];
    for (const param in req.query) {
      if (!allowedParams.includes(param)) {
        return res.status(400).json({
          error: `Query parameter '${param}' not allowed`
        });
      }
    }

    // Validate and sanitize limit parameter
    let limit = 10;
    if (req.query.limit) {
      const parsedLimit = parseInt(req.query.limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Limit must be a number between 1 and 100'
        });
      }
      limit = parsedLimit;
    }

    // In a real app, this data would come from a database with proper filtering
    const mockUsers = [
