/**
 * Centralized error handling middleware
 * Implements security best practices for error handling
 */

const winston = require('winston');

// Configure logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

// If we're not in production, log to the console with a simple format
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

/**
 * Error handling middleware
 * @param {Error} err - The error object
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Next middleware function
 */
const errorHandler = (err, req, res, next) => {
  // Log the error details (without exposing sensitive information)
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });

  // Determine the status code
  const statusCode = res.statusCode === 200 ? 500 : res.statusCode;

  // Set the status code
  res.status(statusCode);

  // Don't expose detailed error messages in production
  if (process.env.NODE_ENV === 'production') {
    res.json({
      success: false,
      message: 'Internal server error'
    });
  } else {
    // In development, provide detailed error information
    res.json({
      success: false,
      message: err.message,
      stack: err.stack
    });
  }
};

/**
 * Not found handler
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Next middleware function
 */
const notFound = (req, res, next) => {
  const error = new Error(`Not Found - ${req.originalUrl}`);
  res.status(404);
  next(error);
};

module.exports = { errorHandler, notFound };

/**
 * Security middleware
 * Implements security best practices
 */

const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');

/**
 * Rate limiting middleware
 * Prevents brute force attacks and DoS attacks
 */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    success: false,
    message: 'Too many requests from this IP, please try again later.'
  },
  headers: true,
});

/**
 * CORS configuration
 * Restricts cross-origin requests
 */
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200 // For legacy browser support
};

/**
 * Security middleware configuration
 * @returns {Array} Array of security middleware functions
 */
const securityMiddleware = [
  // Security headers
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"]
      }
    },
    hsts: {
      maxAge: 31536000, // Must be at least 1 year to be approved
      includeSubDomains: true, // Must be enabled to be approved
      preload: true
    }
  }),

  // Parse JSON bodies
  express => {
    express.use(express.json({
      limit: '10kb' // Limit request body size
    }));
  },

  // Rate limiting
  limiter,

  // CORS
  cors(corsOptions),

  // Remove powered-by header (security through obscurity)
  (req, res, next) => {
    res.removeHeader('X-Powered-By');
    next();
  }
];

module.exports = securityMiddleware;

/**
