const express = require('express');
const app = express();

// Simple rate limiting using in-memory storage
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

// Enhanced middleware for security
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Rate limiting
  const clientIP = req.ip || 'unknown';
  const now = Date.now();

  // Clean up old entries
  if (requestCounts.size > 1000) {
    // Simple cleanup if we have too many entries
    const cutoff = now - RATE_LIMIT_WINDOW;
    for (const [ip, data] of requestCounts) {
      if (data.timestamp < cutoff) {
        requestCounts.delete(ip);
      }
    }
  }

  // Check rate limit
  const requestData = requestCounts.get(clientIP);
  if (requestData) {
    if (now - requestData.timestamp < RATE_LIMIT_WINDOW) {
      if (requestData.count >= MAX_REQUESTS) {
        return res.status(429).json({
          error: 'Too many requests',
          message: 'Rate limit exceeded. Please try again later.'
        });
      }
      requestData.count += 1;
    } else {
      // Reset counter if outside window
      requestData.count = 1;
      requestData.timestamp = now;
    }
  } else {
    // New IP
    requestCounts.set(clientIP, {
      count: 1,
      timestamp: now
    });
  }

  // Prevent NoSQL injection (basic)
  if (req.query) {
    for (const key in req.query) {
      const value = req.query[key];
      if (typeof value === 'string' && 
          (value.includes('$') || value.includes('<') || 
           value.includes('>') || value.includes('script'))) {
        return res.status(400).json({
          error: 'Invalid request',
          message: 'Request contains potentially malicious content'
        });
      }
    }
  }

  next();
});

// Parse JSON with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Improved health check with error handling
app.get('/health', (req, res) => {
