// Security best practices with built-in Express features

// Set security HTTP headers
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent caching of sensitive data
  res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  next();
});

// Limit request body size to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Validate query parameters
  if (req.query && Object.keys(req.query).length > 10) {
    return res.status(400).json({
      error: 'Too many query parameters',
      message: 'Request contains an excessive number of query parameters'
    });
  }

  // Sanitize query parameters (basic)
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      // Simple SQL injection prevention
      if (/[;'"=()]/.test(req.query[key])) {
        return res.status(400).json({
          error: 'Invalid characters in request',
          message: 'Request contains potentially malicious characters'
        });
      }

      // Check for common XSS patterns
      if (/<script|javascript:|on\w+=/i.test(req.query[key])) {
        return res.status(400).json({
          error: 'Potential XSS attack detected',
          message: 'Request contains potentially malicious script content'
        });
      }
    }
  });

  next();
};

