const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.hidePoweredBy()); // Removes X-Powered-By header

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Enable CORS with restrictions
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
}));

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true // Only parse objects and arrays
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path} ${req.ip}`);
  next();
});

// Input validation middleware for users route
const validateUsersQuery = (req, res, next) => {
  // Example validation - you can expand this based on requirements
  if (req.query.limit && (isNaN(req.query.limit) || parseInt(req.query.limit) <= 0 || parseInt(req.query.limit) > 100)) {
    return res.status(400).json({
      error: 'Invalid limit parameter. Must be a number between 1 and 100.'
    });
  }

  if (req.query.page && (isNaN(req.query.page) || parseInt(req.query.page) <= 0)) {
    return res.status(400).json({
      error: 'Invalid page parameter. Must be a positive number.'
    });
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Add any additional health checks here
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with validation
app.get('/users', validateUsersQuery, (req, res) => {
  try {
    // In a real application, this would query a database
    // For now, returning hardcoded data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination if requested
    const limit = req.query.limit ? parseInt(req.query.limit) : users.length;
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    // Filter users based on pagination
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Return response with pagination info
    res.json({
      data: paginatedUsers,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(users.length / limit),
        totalCount: users.length,
        limit: limit
      }
    });

  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' 
        ? 'An error occurred while processing your request' 
        : error.message
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The endpoint ${req.method} ${req.path} does not exist.`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: error.message
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  // Default to 500 for all other errors
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An error occurred while processing your request' 
      : error.message
  });
});

const PORT = process.env.PORT || 3000;
const SERVER = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing HTTP server');
  SERVER.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: closing HTTP server');
  SERVER.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

