const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(mongoSanitize()); // NoSQL injection protection
app.use(xss()); // XSS protection

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const { id } = req.params;

  // Validate ID is a positive integer
  if (id !== undefined) {
    const numId = parseInt(id, 10);
    if (isNaN(numId) || numId <= 0 || !Number.isInteger(numId)) {
      return res.status(400).json({
        error: 'Invalid ID parameter',
        message: 'ID must be a positive integer'
      });
    }
  }
  next();
};

// Improved health endpoint with better error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if needed
    const allowedParams = ['verbose', 'format'];
    const queryParams = Object.keys(req.query);

    for (const param of queryParams) {
      if (!allowedParams.includes(param)) {
        return res.status(400).json({
          error: 'Invalid query parameter',
          message: `Query parameter '${param}' is not allowed`
        });
      }
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    // Add verbose info if requested
    if (req.query.verbose === 'true') {
      healthData.service = 'user-service';
      healthData.version = '1.0.0';
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Enhanced users endpoint with filtering and validation
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { limit, page, search } = req.query;

    // Validate and sanitize query parameters
    let validatedLimit = 10;
    let validatedPage = 1;
    let validatedSearch = null;

    if (limit !== undefined) {
      const numLimit = parseInt(limit, 10);
      if (isNaN(numLimit) || numLimit < 1 || numLimit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be an integer between 1 and 100'
        });
      }
      validatedLimit = numLimit;
    }

    if (page !== undefined) {
      const numPage = parseInt(page, 10);
      if (isNaN(numPage) || numPage < 1) {
        return res.status(400).json({
          error: 'Invalid page parameter',
          message: 'Page must be a positive integer'
        });
      }
      validatedPage = numPage;
    }

    if (search !== undefined) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({
          error: 'Invalid search parameter',
          message: 'Search must be a string with maximum 50 characters'
        });
      }
      validatedSearch = search.trim();
    }

    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided
    if (validatedSearch) {
      const searchLower = validatedSearch.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const startIndex = (validatedPage - 1) * validatedLimit;
    const paginatedUsers = users.slice(startIndex, startIndex + validatedLimit);

    // Return response with metadata
