const app = express();

// Security middleware - should be early in the stack
app.use(SecurityConfig.securityHeaders());
app.use(SecurityConfig.rateLimit());

// Enable CORS with security restrictions
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

