// Get user by ID with input validation
app.get('/users/:id', (req, res) => {
  const { id } = req.params;

  // Validate ID is a number
  if (!/^[0-9]+$/.test(id)) {
    return res.status(400).json({
      error: 'Invalid user ID',
      message: 'User ID must be a positive integer'
    });
  }

  const userId = parseInt(id);
  const user = findUserById(userId);

  if (!user) {
    return res.status(404).json({
      error: 'User not found',
      message: `No user found with ID ${userId}`
    });
  }

  res.json(user);
});

// Create new user with validation
const { validateUserInput } = require('./middleware/security');

app.post('/users', validateUserInput, (req, res) => {
  try {
    const newUser = {
      id: users.length > 0 ? Math.max(...users.map(u => u.id)) + 1 : 1,
      name: req.body.name,
      email: req.body.email
    };

    users.push(newUser);

    // Log user creation
    console.log(`POST /users - Created user ${newUser.id} - ${new Date().toISOString()}`);

    res.status(201).json(newUser);
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to create user'
    });
  }
});

// Update user with validation
app.put('/users/:id', validateUserInput, (req, res) => {
  const { id } = req.params;

  if (!/^[0-9]+$/.test(id)) {
    return res.status(400).json({
      error: 'Invalid user ID',
      message: 'User ID must be a positive integer'
    });
  }

  const userId = parseInt(id);
  const userIndex = users.findIndex(user => user.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({
      error: 'User not found',
      message: `No user found with ID ${userId}`
    });
  }

  try {
    // Update user information
    users[userIndex] = {
      ...users[userIndex],
      name: req.body.name,
      email: req.body.email
    };

    // Log user update
