const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api/', limiter);

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Input validation schema for user data
const userSchema = Joi.object({
  id: Joi.number().integer().min(1).required(),
  name: Joi.string().max(100).required(),
  email: Joi.string().email().max(255).required()
});

// Health check endpoint
app.get('/health', (req, res) => {
  // No input to validate for health check
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any
    const { error } = Joi.object({
      limit: Joi.number().integer().min(1).max(100),
      offset: Joi.number().integer().min(0)
    }).validate(req.query);

    if (error) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: error.details.map(detail => detail.message)
      });
    }

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate the response data
    for (const user of users) {
      const { error: validationError } = userSchema.validate(user);
      if (validationError) {
        console.error('Invalid user data:', validationError);
        return res.status(500).json({
          error: 'Internal server error'
        });
      }
    }

    res.json(users);
  } catch (err) {
    console.error('Error in /users endpoint:', err);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

