const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  // Remove Express version header
  res.removeHeader('X-Powered-By');
  next();
});

// Enable CORS with strict origin policies for production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || false, // Only allow specific origins
  credentials: true,
}));

// Input validation middleware for all routes
app.use((req, res, next) => {
  try {
    // Validate and sanitize query parameters
    if (req.query) {
      Object.keys(req.query).forEach(key => {
        if (typeof req.query[key] === 'string') {
          // Basic XSS prevention for query parameters
          const value = req.query[key];
          if (value.match(/<script|javascript:/i)) {
            return res.status(400).json({
              error: 'Invalid query parameter: potential XSS attack detected'
            });
          }

          // Prevent path traversal
          if (value.includes('../') || value.includes('..\\')) {
            return res.status(400).json({
              error: 'Invalid query parameter: path traversal attempt detected'
            });
          }
        }
      });
    }

    // Check request size
    const contentLength = req.headers['content-length'];
    if (contentLength && parseInt(contentLength) > 1024 * 1024) { // 1MB limit
      return res.status(413).json({
        error: 'Payload too large'
      });
    }

    next();
  } catch (error) {
    console.error('Error in input validation middleware:', error);
    return res.status(400).json({
      error: 'Invalid request format'
    });
  }
});

// Health check with proper error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    if (Object.keys(req.query).length > 0) {
      const validParams = ['verbose']; // Example of allowed parameters
      const invalidParams = Object.keys(req.query).filter(param => 
        !validParams.includes(param)
      );

      if (invalidParams.length > 0) {
        return res.status(400).json({
          error: `Invalid query parameters: ${invalidParams.join(', ')}`,
          validParams: validParams
        });
      }
    }

    const healthStatus = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    // Add verbose info if requested
    if (req.query.verbose) {
      healthStatus.hostname = require('os').hostname();
      healthStatus.pid = process.pid;
    }

    res.json(healthStatus);
  } catch (error) {
    console.error('Error in /health route:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { page, limit, sort } = req.query;

    // Validate pagination parameters
    let pageInt = 1;
    let limitInt = 10;

    if (page !== undefined) {
      pageInt = parseInt(page);
      if (isNaN(pageInt) || pageInt < 1) {
        return res.status(400).json({
          error: 'Page parameter must be a positive integer'
        });
      }
    }

    if (limit !== undefined) {
      limitInt = parseInt(limit);
      if (isNaN(limitInt) || limitInt < 1 || limitInt > 100) {
        return res.status(400).json({
          error: 'Limit parameter must be a positive integer between 1 and 100'
        });
      }
    }

    // Validate sort parameter
    const allowedSortFields = ['name', 'email', 'id'];
    if (sort !== undefined) {
      if (!allowedSortFields.includes(sort)) {
        return res.status(400).json({
          error: `Sort field must be one of: ${allowedSortFields.join(', ')}`
        });
      }
    }

    // Mock user data (in real app, this would come from a database)
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Evan', email: 'evan@example.com' },
    ];

    // Apply sorting if specified
    let users = [...mockUsers];
    if (sort) {
      users.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    // Apply pagination
    const startIndex = (pageInt - 1) * limitInt;
    const paginatedUsers = users.slice(startIndex, startIndex + limitInt);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        page: pageInt,
        limit: limitInt,
        total: mockUsers.length,
        pages: Math.ceil(mockUsers.length / limitInt)
      }
    });

  } catch (error) {
    console.error('Error in /users route:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: error.message
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: error.message
    });
  }

  // All other errors
  res.status(500).json({ 
    error: 'Internal server error',
    timestamp: new Date().toISOString() 
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);

  // Security note
  if (process.env.NODE_ENV !== 'production') {
    console.log('⚠️  Development mode - ensure proper security settings in production');
  }
});

module.exports = app;

