const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

app.use('/api/', limiter);

// CORS configuration
const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// API Health Check
app.get('/health', [
  // Validate query parameters if any
  query('detailed').optional().isBoolean().withMessage('Detailed must be boolean'),
], (req, res) => {
  // Check validation results
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array() 
    });
  }

  const detailed = req.query.detailed === 'true';

  const response = { 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  };

  if (detailed) {
    response.host = req.hostname;
    response.protocol = req.protocol;
  }

  res.json(response);
});

// Users endpoint with improved security
app.get('/users', [
  // Add query parameter validation
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
], (req, res) => {
  // Check validation results
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array()
    });
  }

  // Extract and validate query parameters
  const limit = req.query.limit ? parseInt(req.query.limit) : 10;
  const offset = req.query.offset ? parseInt(req.query.offset) : 0;

  // Mock data filtering based on parameters
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' }
  ];

  // Apply pagination
  const paginatedUsers = allUsers
    .slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit,
      offset,
      total: allUsers.length,
      next: offset + limit < allUsers.length ? `/users?limit=${limit}&offset=${offset + limit}` : null,
      previous: offset > 0 ? `/users?limit=${limit}&offset=${Math.max(0, offset - limit)}` : null
    }
  });
});

// User detail endpoint
app.get('/users/:id', [
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array()
    });
  }

  const userId = parseInt(req.params.id);

  // Mock user lookup
  const user = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ].find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ 
      error: 'User not found'
    });
  }

  res.json(user);
});

// 404 handler for undefined routes
