const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const logger = require('morgan');

const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.hidePoweredBy());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// Request logging
if (process.env.NODE_ENV !== 'test') {
  app.use(logger('dev'));
}

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request size
}));

// Validate and sanitize input
const sanitizeInput = (req, res, next) => {
  // Simple input sanitization
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }
  next();
};

app.use(sanitizeInput);

// Health check route
app.get('/health', (req, res) => {
  // Input validation
  if (req.query && Object.keys(req.query).length > 5) {
    return res.status(400).json({
      error: 'Too many query parameters'
    });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users route
app.get('/users', (req, res) => {
  try {
    // Input validation
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;

    // Validate pagination parameters
    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Page must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Limit must be a positive integer between 1 and 100'
      });
    }

    // In a real application, you would fetch users from a database
    // with proper pagination based on page and limit
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: 2,
        totalPages: Math.ceil(2 / limit)
      }
    });

  } catch (error) {
    console.error('Error in /users route:', error);

    // Generic error message to avoid exposing system details
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`
  });
});

// Error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Never expose stack traces in production
  const errorResponse = {
    error: 'Internal server error'
  };

  // Add error details only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = error.message;
    errorResponse.stack = error.stack;
  }

  res.status(500).json(errorResponse);
});

// Graceful shutdown
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

server.on('error', (error) => {
  console.error('Server error:', error);
});

module.exports = app;

