const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.frameguard({ action: 'deny' }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200
}));

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateUserParams = (req, res, next) => {
  // Example: if we had user ID validation
  if (req.params.id) {
    const userId = parseInt(req.params.id);
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID format'
      });
    }
  }
  next();
};

app.get('/health', (req, res) => {
  // Input validation
  if (req.query && Object.keys(req.query).length > 0) {
    return res.status(400).json({
      error: 'Health check endpoint does not accept query parameters'
    });
  }

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validateUserParams, (req, res) => {
  // Validate query parameters if any
  if (req.query.search && typeof req.query.search !== 'string') {
    return res.status(400).json({
      error: 'Search parameter must be a string'
    });
  }

  // Simulate data filtering if needed
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Example of search filtering (would normally go to database)
  if (req.query.search) {
    const searchTerm = req.query.search.toLowerCase();
    users = users.filter(user => 
      user.name.toLowerCase().includes(searchTerm) || 
      user.email.toLowerCase().includes(searchTerm)
    );
  }

  // Add result metadata
  res.json({
    success: true,
    count: users.length,
    data: users
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err.stack);

  // Hide internal error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: isProduction 
      ? 'Internal server error'
      : err.message || 'Internal server error',
    // Include stack trace only in development
    ...(isProduction ? {} : { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;

