# Security and Error Handling Review of app.js

## Current Issues Identified:

1. **Missing Error Handling**: The application has no proper error handling mechanisms.
2. **No Input Validation**: The routes don't validate or sanitize any inputs.
3. **Missing Security Headers**: No protection against common web vulnerabilities.
4. **No Rate Limiting**: Vulnerable to denial of service attacks.
5. **Missing Middleware for Security**: No body parser with limits, no XSS protection.
6. **Insecure Dependencies**: No package.json to manage dependencies securely.
7. **No Input Sanitization**: Potential for injection attacks if routes are expanded.
8. **Missing HTTPS**: No secure transport layer implementation.

## Recommended Improvements:

```javascript
// Improved version with security best practices
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize data against XSS
app.use(mongoSanitize()); // Sanitize query parameters, body, etc.

// Prevent parameter pollution
app.use(hpp());

// Limit request size
app.use(express.json({ limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // Validate inputs
    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid query parameters. Page and limit must be positive numbers. Limit max: 100'
      });
    }

    // Mock data (would be from database in real app)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement basic pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.status(200).json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        current: page,
        total: Math.ceil(users.length / limit),
        hasNext: page < Math.ceil(users.length / limit),
        hasPrev: page > 1
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Failed to retrieve users',
      timestamp: new Date().toISOString()
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Cannot ${req.method} ${req.originalUrl}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  res.status(500).json({
    status: 'error',
    message: 'Something went very wrong!',
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (error) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(error);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(error);
  process.exit(1);
});

module.exports = app;
```

## Required package.json updates:

```json
{
  "name": "secure-express-app",
  "version": "1.0.0",
  "description": "Express app with security best practices",
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.14.0",
    "xss-clean": "^0.1.4",
    "express-mongo-sanitize": "^2.2.0",
    "hpp": "^0.2.3"
  },
  "scripts": {
    "start": "node app.js"
  }
}
```

## Additional Security Recommendations:

1. **Environment Variables**: Use dotenv for managing environment variables including database credentials, API keys, etc.

2. **CORS Configuration**: Implement proper CORS if serving different domains:
```javascript
const cors = require('cors');
app.use(cors({ origin: 'https://yourdomain.com' }));
```

3. **HTTPS Implementation**: Use TLS/SSL in production:
```javascript
const https = require('https');
const fs = require('fs');
// In production
// const server = https.createServer(options, app).listen(443);
```

4. **Logging**: Implement proper logging with tools like Winston or Morgan.

5. **Input Validation**: For more complex validation, consider using Joi or express-validator.

6. **Authentication/Authorization**: Implement JWT or OAuth2 for protected routes.

7. **Dependency Monitoring**: Use tools like npm audit, Snyk, or Dependabot to monitor for vulnerable dependencies.

These improvements significantly enhance the security posture, error handling, and input validation of your Express application, following Node.js and Express security best practices.

