  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});

// Apply rate limiter to all requests
app.use(limiter);

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request size
}));

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Check for suspicious headers or patterns
  const suspiciousHeaders = ['<script>', 'javascript:', 'onerror=', 'onload='];

  for (const [key, value] of Object.entries(req.headers)) {
    if (typeof value === 'string') {
      const lowerValue = value.toLowerCase();
      if (suspiciousHeaders.some(pattern => lowerValue.includes(pattern))) {
        return res.status(400).json({
          error: 'Invalid request headers'
        });
      }
    }
  }

  next();
};

app.use(validateRequest);

// Health check endpoint
app.get('/health', (req, res) => {
  // Validate query parameters if any
  if (req.query && Object.keys(req.query).length > 0) {
    return res.status(400).json({
      error: 'Health check endpoint does not accept query parameters'
    });
  }

  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;

    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Page must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Limit must be a positive integer between 1 and 100'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: error.message
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: error.message
    });
  }

  // Default to 500 for all other errors
  res.status(500).json({
    error: 'Internal server error'
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

