const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const sanitize = require('express-mongo-sanitize');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Data sanitization against NoSQL injection
app.use(sanitize());

// Enhanced JSON parsing with size limits
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Set timeout for requests
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 second timeout
  next();
});

// Health check endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    // Validate request
    if (req.query && Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'Health check endpoint does not accept query parameters'
      });
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    res.status(200).json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint with query parameter validation
app.get('/users', (req, res) => {
  try {
    // Extract and validate query parameters
    const { limit, offset, name } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      const limitNum = parseInt(limit);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter. Must be a number between 1 and 100.',
          example: '/users?limit=10'
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      const offsetNum = parseInt(offset);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Invalid offset parameter. Must be a non-negative number.',
          example: '/users?offset=10'
        });
      }
    }

    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by name if provided
    if (name) {
      if (typeof name !== 'string' || name.length > 50) {
        return res.status(400).json({
          error: 'Invalid name parameter. Must be a string with maximum 50 characters.',
          example: '/users?name=Alice'
        });
      }

      const searchTerm = name.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply limit and offset for pagination
    const limitNum = limit ? parseInt(limit) : users.length;
    const offsetNum = offset ? parseInt(offset) : 0;

    const paginatedUsers = users.slice(offsetNum, offsetNum + limitNum);

    // Return response with metadata
    res.status(200).json({
      data: paginatedUsers,
      total: users.length,
      limit: limitNum,
      offset: offsetNum,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users',
      timestamp: new Date().toISOString() 
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    method: req.method
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  res.status(500).json({
    error: 'Internal server error',
    message: 'Something went wrong!',
    timestamp: new Date().toISOString()
  });
});

// Get port from environment variable with fallback
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Node.js environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;

