const express = require('express');
const app = express();

// Security headers middleware (built-in)
app.use((req, res, next) => {
  // Basic security headers - equivalent to helmet()
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'; frame-ancestors 'none'");

  // Set request timeout
  req.setTimeout(30000, () => {
    res.status(408).json({
      error: 'Request timeout',
      message: 'The request took too long to process'
    });
  });

  next();
});

// Enhanced JSON parsing with limits
app.use(express.json({
  limit: '10kb', // Limit request body size to prevent DOS attacks
  verify: (req, res, buf) => {
    // Additional validation of JSON payload size
    if (buf.length > 10 * 1024) { // 10KB
      throw new Error('Payload too large');
    }
  }
}));

// Simple rate limiting object to track requests
const requestRateLimit = {};
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes in ms
const MAX_REQUESTS = 100; // Max requests per window

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean old entries
  Object.keys(requestRateLimit).forEach(key => {
    if (requestRateLimit[key].timestamp < now - RATE_LIMIT_WINDOW) {
      delete requestRateLimit[key];
    }
  });

  // Initialize IP entry if needed
  if (!requestRateLimit[ip]) {
    requestRateLimit[ip] = {
      count: 0,
      timestamp: now
    };
  }

  // Check if rate limit exceeded
  if (requestRateLimit[ip].count >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests',
      message: `Rate limit exceeded. Maximum ${MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW/60000} minutes.`,
      retryAfter: RATE_LIMIT_WINDOW - (now - requestRateLimit[ip].timestamp)
    });
  }

  // Increment request count
  requestRateLimit[ip].count++;
  next();
});

// Input sanitization middleware
