app.get('/health', (req, res) => {
  try {
    // Input validation - check for malicious query parameters
    const maliciousParams = Object.keys(req.query).some(
      key => key.toLowerCase().includes('script') || 
              key.toLowerCase().includes('onerror') ||
              key.toLowerCase().includes('onload')
    );

    if (maliciousParams) {
      return res.status(400).json({
        error: 'Invalid request parameters'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Users endpoint with improved security
app.get('/users', (req, res) => {
  try {
    // Validate query parameters to prevent injection attacks
    if (Object.keys(req.query).length > 3) { // Limit number of query params
      return res.status(400).json({
        error: 'Too many query parameters'
      });
    }

    // Filter out potentially dangerous query parameter names
    const invalidParam = Object.keys(req.query).find(
      key => !/^[a-zA-Z0-9_]+$/.test(key)
    );

    if (invalidParam) {
      return res.status(400).json({
        error: 'Invalid query parameter name'
      });
    }

    // In a real application, this data would come from a database
