const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(cors()); // Enable CORS with default settings
app.use(xss()); // Sanitizes user input to prevent XSS

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting - 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  headers: true,
});

app.use('/api', limiter);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    // Validate request - check for unexpected parameters
    const allowedParams = ['format']; // Example of allowed optional parameter
    const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: `The following parameters are not allowed: ${invalidParams.join(', ')}`
      });
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.VERSION || '1.0.0'
    };

    // Optional formatting based on query param
    if (req.query.format === 'detailed') {
      healthData.environment = process.env.NODE_ENV || 'development';
      healthData.uptime = process.uptime();
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page, limit, sort } = req.query;

    // Input validation
    if (page && (!Number.isInteger(Number(page)) || Number(page) < 1)) {
      return res.status(400).json({
        error: 'Invalid page parameter',
        message: 'Page must be a positive integer'
      });
    }

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be a positive integer between 1 and 100'
      });
    }

    if (sort && !['name', 'id', 'email'].includes(sort)) {
      return res.status(400).json({
        error: 'Invalid sort parameter',
        message: 'Sort must be one of: name, id, email'
      });
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination and sorting if requested
    let result = [...users];

    if (sort) {
      result.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    const pageNumber = page ? Number(page) : 1;
    const limitNumber = limit ? Number(limit) : 10;
    const startIndex = (pageNumber - 1) * limitNumber;
    const endIndex = startIndex + limitNumber;

    const paginatedResult = result.slice(startIndex, endIndex);

    // Return response with metadata
    res.json({
      data: paginatedResult,
      pagination: {
        page: pageNumber,
        limit: limitNumber,
        total: users.length,
        pages: Math.ceil(users.length / limitNumber)
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details in production
  const isProd = process.env.NODE_ENV === 'production';

  res.status(err.statusCode || 500).json({
    error: isProd ? 'Internal server error' : err.message,
    message: isProd ? 'An unexpected error occurred' : err.message,
    ...(isProd ? {} : { stack: err.stack })
  });
});

// Handle 404 routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The requested route ${req.method} ${req.originalUrl} does not exist`
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

