// Input validation middleware
const validator = require('validator');

const validateUserInput = (req, res, next) => {
  const { name, email } = req.body;

  // Validate name
  if (!name || typeof name !== 'string' || name.trim().length === 0) {
    return res.status(400).json({
      error: 'Invalid name provided',
      message: 'Name is required and must be a non-empty string'
    });
  }

  // Validate name length
  if (name.trim().length < 2 || name.trim().length > 100) {
    return res.status(400).json({
      error: 'Invalid name length',
      message: 'Name must be between 2 and 100 characters'
    });
  }

  // Validate email if provided
  if (email !== undefined) {
    if (!email || !validator.isEmail(email)) {
      return res.status(400).json({
        error: 'Invalid email format',
        message: 'Valid email format is required if email is provided'
      });
    }
  }

  // Sanitize inputs
  req.body.name = name.trim();
  if (email) req.body.email = email.trim().toLowerCase();

  next();
};

module.exports = {
  validateUserInput
};

// Centralized error handling middleware

const errorHandler = (err, req, res, next) => {
  // Log the error (in a real app, use a proper logging library)
  console.error('Error:', err);

  // Determine the error status code
  const statusCode = err.statusCode || err.status || 500;

  // Security: Don't expose sensitive error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(statusCode).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }

  // In development, provide more detailed error information
  return res.status(statusCode).json({
    error: err.message || 'Internal server error',
    message: err.message,
    stack: err.stack,
    // Include additional error properties if they exist
    ...(err.statusCode && { statusCode: err.statusCode }),
    ...(err.code && { code: err.code }),
    ...(err.details && { details: err.details })
  });
};

// Specific error for invalid JSON in request body
const handleJsonParseError = (err, req, res, next) => {
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'Request body contains invalid JSON'
    });
  }
  next(err);
};

module.exports = {
  errorHandler,
  handleJsonParseError
};

